// ---------------------------------------------------------------------------
// Little drawings
// ---------------------------------------------------------------------------

function sparkle(cx: number, cy: number, r: number, fill: Hex = M.gold): Shape {
  const s = r * 0.28;
  return {
    kind: 'polygon',
    points: `${cx},${cy - r} ${cx + s},${cy - s} ${cx + r},${cy} ${cx + s},${cy + s} ${cx},${cy + r} ${cx - s},${cy + s} ${cx - r},${cy} ${cx - s},${cy - s}`,
    fill,
  };
}

function cloud(x: number, y: number, w: number): Shape {
  const h = w * 0.38;
  return {
    kind: 'path',
    d: `M${x} ${y + h} Q${x - w * 0.08} ${y + h * 0.35} ${x + w * 0.22} ${y + h * 0.45} Q${x + w * 0.3} ${y - h * 0.2} ${x + w * 0.58} ${y + h * 0.25} Q${x + w * 0.85} ${y} ${x + w * 0.95} ${y + h * 0.55} Q${x + w * 1.1} ${y + h} ${x + w} ${y + h} Z`,
    fill: M.white,
    stroke: M.edge,
    strokeWidth: 1,
    opacity: 0.9,
  };
}

function bird(x: number, y: number): Shape {
  return { kind: 'path', d: `M${x - 5} ${y} Q${x - 2.5} ${y - 4} ${x} ${y} Q${x + 2.5} ${y - 4} ${x + 5} ${y}`, fill: 'none', stroke: M.ink, strokeWidth: 1.2, opacity: 0.6 };
}

function curl(x: number, y: number, sx: 1 | -1, sy: 1 | -1): Shape {
  return {
    kind: 'path',
    d: `M${x} ${y + 30 * sy} Q${x} ${y} ${x + 30 * sx} ${y} M${x + 9 * sx} ${y + 18 * sy} Q${x + 9 * sx} ${y + 9 * sy} ${x + 18 * sx} ${y + 9 * sy}`,
    fill: 'none',
    stroke: M.edge,
    strokeWidth: 2,
  };
}

/** A carousel seen from above: a striped canopy. */
function carrousel(c: Pt, r: number): Shape[] {
  const out: Shape[] = [{ kind: 'circle', cx: c.x, cy: c.y, r: r + 1.5, fill: M.walk, stroke: M.edge, strokeWidth: 0.8 }];
  for (let k = 0; k < 12; k++) {
    const a1 = (k * Math.PI) / 6;
    const a2 = ((k + 1) * Math.PI) / 6;
    out.push({
      kind: 'polygon',
      points: `${c.x},${c.y} ${(c.x + r * Math.cos(a1)).toFixed(1)},${(c.y + r * Math.sin(a1)).toFixed(1)} ${(c.x + r * Math.cos(a2)).toFixed(1)},${(c.y + r * Math.sin(a2)).toFixed(1)}`,
      fill: k % 2 ? M.gold : M.red,
    });
  }
  out.push({ kind: 'circle', cx: c.x, cy: c.y, r: 2, fill: M.white, stroke: M.ink, strokeWidth: 0.6 });
  return out;
}

/** Spinning cups seen from above. */
function teacups(c: Pt): Shape[] {
  const colors: Hex[] = [M.rose, M.blue, M.gold, M.lilac, '#8ACB7A'];
  return [
    { kind: 'circle', cx: c.x, cy: c.y, r: 11, fill: M.walk, stroke: M.edge, strokeWidth: 0.8 },
    ...colors.map((fill, i): Shape => {
      const a = (i / colors.length) * Math.PI * 2;
      return { kind: 'circle', cx: +(c.x + 6.5 * Math.cos(a)).toFixed(1), cy: +(c.y + 6.5 * Math.sin(a)).toFixed(1), r: 2.6, fill, stroke: M.ink, strokeWidth: 0.5 };
    }),
  ];
}

/** A generic flying ride: a hub with arms and little round cars. */
function spinner(c: Pt): Shape[] {
  const out: Shape[] = [{ kind: 'circle', cx: c.x, cy: c.y, r: 10, fill: M.walk, stroke: M.edge, strokeWidth: 0.8 }];
  for (let k = 0; k < 8; k++) {
    const a = (k * Math.PI) / 4;
    const x = c.x + 7.5 * Math.cos(a), y = c.y + 7.5 * Math.sin(a);
    out.push({ kind: 'line', x1: c.x, y1: c.y, x2: +x.toFixed(1), y2: +y.toFixed(1), stroke: M.gold, strokeWidth: 0.8 });
    out.push({ kind: 'circle', cx: +x.toFixed(1), cy: +y.toFixed(1), r: 1.6, fill: k % 2 ? M.rose : M.blue });
  }
  out.push({ kind: 'circle', cx: c.x, cy: c.y, r: 2, fill: M.gold });
  return out;
}

/** A white ribbed dome. */
function ribbedDome(c: Pt, r: number): Shape[] {
  return [
    { kind: 'circle', cx: c.x, cy: c.y, r, fill: M.white, stroke: M.steel, strokeWidth: 1.2 },
    ...Array.from({ length: 16 }, (_, k): Shape => ({
      kind: 'line',
      x1: c.x,
      y1: c.y,
      x2: +(c.x + r * Math.cos((k * Math.PI) / 8)).toFixed(1),
      y2: +(c.y + r * Math.sin((k * Math.PI) / 8)).toFixed(1),
      stroke: M.steel,
      strokeWidth: 0.9,
    })),
    { kind: 'circle', cx: c.x, cy: c.y, r: r * 0.22, fill: M.steel },
  ];
}

/** A snowy cap on a mountain peak seen from above. */
function snowCap(c: Pt, r: number): Shape {
  const pts: string[] = [];
  for (let i = 0; i < 14; i++) {
    const rr = i % 2 ? r * 0.45 : r;
    const a = (i / 14) * Math.PI * 2 + 0.2;
    pts.push(`${(c.x + rr * Math.cos(a)).toFixed(1)},${(c.y + rr * Math.sin(a)).toFixed(1)}`);
  }
  return { kind: 'polygon', points: pts.join(' '), fill: M.white, stroke: '#D8DCE6', strokeWidth: 0.6 };
}

