// ---------------------------------------------------------------------------
// Lands: where to label them, how to zoom in, and stand-in stamp routes
// ---------------------------------------------------------------------------

export type ParkLand = {
  /** lands.id */
  id: string;
  /** Where the land's medallion and label sit on the whole-park map. */
  label: Pt;
  /** The part of the canvas shown when the land is chosen. */
  view: { x: number; y: number; w: number; h: number };
  /** Walking routes used for spots that aren't pinned yet (one per quest in the land). */
  lanes: Pt[][];
};

/**
 * Where each land's medallion sits on the whole-park map: inside the land,
 * spread out so neighbors don't overlap (the middle of the park is crowded).
 */
const LABEL_AT: Record<string, Pt> = {
  'dlp-galaxys-edge': { x: 190, y: 225 },
  'dlp-toontown': { x: 480, y: 118 },
  'dlp-fantasyland': { x: 475, y: 300 },
  'dlp-tomorrowland': { x: 700, y: 470 },
  'dlp-frontierland': { x: 335, y: 440 },
  'dlp-bayou-country': { x: 100, y: 445 },
  'dlp-new-orleans-square': { x: 160, y: 570 },
  'dlp-adventureland': { x: 330, y: 680 },
  'dlp-main-street': { x: 460, y: 730 },
};

export const PARK_LANDS: ParkLand[] = Object.entries(PARK_GEO_LANDS).map(([id, land]) => ({
  id,
  label: LABEL_AT[id] ?? land.label,
  view: land.view,
  lanes: land.lanes,
}));

